for(const p of extra){const old=d.products.find(x=>x.id===p.id);if(old)Object.assign(old,p);else d.products.push({...p,stock:32,eligible:true,own:false})}
const rxProducts=[{id:'p6',brand:'Evolan',name:'Hydrokortison Evolan',size:'10 mg/g · Salve · 50 g',image:'assets/rx-hydrokortison.webp',desc:'Salve med hydrokortison. Pakningsinformasjon og forskrevet bruk følger resepten.'},{id:'p10',brand:'Sandoz',name:'Cetirizin Sandoz',size:'10 mg · Tabletter · 30 stk.',image:'assets/rx-cetirizin.webp',desc:'Cetirizintabletter. Dosering vises sammen med den enkelte resepten.'},{id:'p11',brand:'Orifarm',name:'Solvipect',size:'20 mg/ml · Mikstur · 250 ml',image:'assets/rx-solvipect.webp',desc:'Mikstur med guaifenesin. Denne pakningen er valgt fra reseptoversikten.'},{id:'p12',brand:'Evolan',name:'Hydrokortison Evolan',size:'10 mg/g · Salve · 50 g',image:'assets/rx-hydrokortison.webp',desc:'Tidligere forskrivning av salve med hydrokortison.'}];
for(const p of rxProducts)Object.assign(d.products.find(x=>x.id===p.id),p);
const descriptions={p1:'Fuktighetskrem for daglig pleie av tørr hud.',p2:'Solpleie til ansiktet fra La Roche-Posay.',p3:'Håndkrem fra CeraVe til daglig pleie.',p4:'Ansiktsrens fra CeraVe.',p5:'Førstehjelpspakke med plaster, kompresser og bandasjer.',p7:'Fluorskyll fra Flux til den daglige munnpleierutinen.',p8:'Gnagsårplaster fra Compeed. Pakningen inneholder fem plaster.',p9:'Ansiktslotion fra CeraVe.'};
for(const p of d.products)if(descriptions[p.id])p.desc=descriptions[p.id];
const uses={p6:{dosage:'Smøres tynt morgen og kveld',purpose:'Til bruk på huden'},p10:{dosage:'1 tablett én gang daglig',purpose:'Mot allergiplager'},p11:{dosage:'10 ml 3 ganger daglig',purpose:'Ved slimhoste'},p12:{dosage:'Smøres tynt morgen og kveld',purpose:'Til bruk på huden'}};
for(const r of d.prescriptions){Object.assign(r,uses[r.product]);r.id=r.id.replace('RX-DEMO-','RX-2026-');r.type=r.status==='expired'?'Utgått resept':'Hvit resept';r.instruction='Eksempelresept i en lokal forhåndsvisning. Ikke en gyldig resept eller personlig doseringsanbefaling.';r.lastPickup=r.lastPickup.replace('Ikke hentet i demoen','Ingen registrerte uttak').replace(' · eksempel','');}
