let n=d.news.find(n=>n.id==='n1');if(n)Object.assign(n,{title:'Apoteket er nå en del av nettsiden vår',body:'Nå finner du reseptoversikten din, kjente apotekvarer og anbefalinger fra fastlegene på samme nettsted. Velg hjemlevering eller hent pakken på et hentested.'});
d.offices=d.offices||[{id:'fjordbyen',name:'Fjordbyen legesenter',city:'Oslo',address:d.clinic.address,phone:d.clinic.phone,email:d.clinic.email,initials:'F',color:'#326b5b',doctors:3},{id:'nordbyen',name:'Nordbyen legesenter',city:'Trondheim',address:'Olav Tryggvasons gate 12, 7011 Trondheim',phone:'73 00 12 34',initials:'N',color:'#5f718f',doctors:5},{id:'bryggen',name:'Bryggen fastlegekontor',city:'Bergen',address:'Strandgaten 20, 5013 Bergen',phone:'55 00 12 34',initials:'B',color:'#a47b5f',doctors:4},{id:'lokken',name:'Løkken legesenter',city:'Oslo',address:'Thorvald Meyers gate 18, 0555 Oslo',phone:'22 00 56 78',initials:'L',color:'#837795',doctors:3}];
