for(const o of d.orders){o.status=o.status==='Sendt'?'Varene er sendt':o.status==='Pakkes'?'Varene pakkes':statuses.includes(o.status)?o.status:'Mottatt';o.history=statuses.slice(0,statuses.indexOf(o.status)+1).map((status,i)=>({status,at:new Date(new Date(o.date).getTime()+i*3600000).toISOString()}));o.shipping.place=o.shipping.mode==='Hentested'?'Post i Butikk, Grønlandsleiret 25, Oslo':'Schweigaards gate 34, 0191 Oslo';o.tracking=o.tracking.replace('DEMO-','707');o.payment='Betalt';for(const item of o.items){if(item.rx){const p=d.products.find(p=>p.id===item.id),r=d.prescriptions.find(r=>r.product===item.id);item.name=p.name;item.dosage=r.dosage;}}}
if(!d.orders.some(o=>o.clinic==='nordbyen')){for(const [i,office]of ['nordbyen','bryggen','lokken'].entries()){let date=new Date();date.setDate(date.getDate()-i-1);let p=d.products.find(p=>p.id===['p13','p14','p16'][i]);p.stock-=2;d.orders.push({id:'HW-'+(1036+i),date:date.toISOString(),clinic:office,patient:['Erik Hansen','Emma Lund','Jonas Berg'][i],items:[{id:p.id,name:p.name,price:p.price,qty:2,eligible:true,rx:false}],shipping:{id:'posten',name:'Posten',mode:'Hentested',price:59,time:'2–3 virkedager',place:'Post i Butikk, '+d.offices.find(c=>c.id===office).city},status:['Mottatt','Varene pakkes','Levert'][i],picked:i>0?[p.id]:[],tracking:'707842361'+i,payment:'Betalt',history:statuses.slice(0,[0,1,3][i]+1).map((status,j)=>({status,at:new Date(date.getTime()+j*3600000).toISOString()}))})}}
