function office(id=db.activeOffice||'fjordbyen'){return db.offices.find(x=>x.id===id)||db.offices[0]}
function patientOrders(){return db.orders.filter(o=>o.patient==='Nora Solheim'&&o.clinic==='fjordbyen')}
function icon(name,cls=''){return `<svg class="ui-icon ${cls}" aria-hidden="true"><use href="#bi-${name}"></use></svg>`}
function roleLauncher(){return `<div class="role-launcher"><button class="role-toggle" aria-expanded="false" aria-controls="rolePanel" onclick="toggleRoles()">${icon('sliders')}<span>Visning</span></button><div id="rolePanel" class="role-panel" hidden><div><strong>Bytt arbeidsflate</strong><button aria-label="Lukk visningsmeny" onclick="toggleRoles()">${icon('x-lg')}</button></div>${[['Pasient','person-circle','Nettside og apotek'],['Legekontor','building','Innhold og inntekter'],['HelseWeb','grid','Legekontorer og drift'],['Lager','box-seam','Håndterminal og pakkestasjon'],['Lege','clipboard-check','Pasientsky · Legesystem']].map(([r,i,t])=>`<button class="role-option ${role===r?'selected':''}" onclick="route('${r}','${r==='Pasient'?'home':'overview'}')">${icon(i)}<span><strong>${r}</strong><small>${t}</small></span>${role===r?icon('check-circle'):''}</button>`).join('')}<button class="role-reset" onclick="resetDemo()">${icon('arrow-clockwise')}Tilbakestill lokale data</button></div></div>`}
function toggleRoles(){let panel=$('#rolePanel'),toggle=$('.role-toggle');panel.hidden=!panel.hidden;toggle.setAttribute('aria-expanded',String(!panel.hidden))}
function useOffice(id){db.activeOffice=id;save();route('Legekontor','overview')}
function cartCategoryTotal(rx){return db.cart.filter(x=>(product(x.id).category==='Reseptvarer')===rx).reduce((s,x)=>s+product(x.id).price*x.qty,0)}
function cartGroups(compact=false){return [true,false].map(rx=>{const rows=db.cart.filter(x=>(product(x.id).category==='Reseptvarer')===rx);if(!rows.length)return '';return `<div class="${compact?'compact-cart-group':'card cart-group'}"><h3>${icon(rx?'capsule':'bag')}${rx?'Reseptvarer':'Apotekvarer'}<span>${rows.reduce((s,x)=>s+x.qty,0)}</span></h3>${rows.map(x=>{const p=product(x.id),r=rx?db.prescriptions.find(r=>r.product===x.id):null;return `<div class="cart-product ${compact?'compact':''}"><div class="cart-product-image">${art(p)}</div><div class="cart-product-copy"><span class="item-kind ${rx?'kind-rx':''}">${rx?'Reseptvare':'Apotekvare'}</span><strong>${esc(p.name)}</strong><small>${esc(p.size)}</small>${r?`<div class="dose-label">${icon('clock')} ${esc(r.dosage)}</div>`:''}${!compact?`<div class="qty"><button aria-label="Fjern én ${esc(p.name)}" onclick="quantity('${p.id}',-1)">−</button><span>${x.qty}</span><button aria-label="Legg til én ${esc(p.name)}" onclick="quantity('${p.id}',1)" ${rx?'disabled':''}>+</button></div>`:`<small>Antall: ${x.qty}</small>`}</div><strong class="cart-line-price">${money(p.price*x.qty)}</strong></div>`}).join('')}</div>`}).join('')}

function fillExampleNumber(button){const input=$('#demoFnr');input.value='';input.classList.remove('is-invalid');button.disabled=true;input.focus();let n=0;const value='14068899999';function typeNext(){if(!document.contains(input))return;input.value=value.slice(0,++n);if(n<value.length)setTimeout(typeNext,85+Math.random()*95);else button.disabled=false}typeNext()}
for(const r of db.prescriptions){r.doctor='d2';r.type=r.status==='expired'?'Utgått resept':'Blå resept';}

function personalRecommendations(){let recs=db.logged?db.recommendations.filter(r=>r.personal&&product(r.product)):[];return `<section class="personal-recommendations-panel" aria-labelledby="personalRecTitle"><div class="personal-recommendations-header"><div><span class="eyebrow">${db.logged?'Bare for deg, Nora':'Dine personlige anbefalinger'}</span><h2 id="personalRecTitle">Anbefalt for deg</h2><p>${db.logged?'Fra konsultasjonen – med legens egen begrunnelse.':'Samlet på ett sted, fra legen som kjenner deg.'}</p></div><span class="personal-rec-privacy">${icon('shield-check')} Personlig</span></div>${!db.logged?`<div class="personal-rec-signin"><div class="personal-signin-illustration">${icon('heart-pulse')}</div><div><h3>Har legen anbefalt deg et produkt?</h3><p>Logg inn for å se anbefalingene dine. De generelle utvalgene nedenfor er åpne for alle.</p></div>${btn('Se mine anbefalinger '+icon('arrow-right'),"startBank('recommendations')")}</div>`:recs.length?`<div class="personal-recommendations-list">${recs.map(personalRecommendationCard).join('')}</div><div class="personal-rec-footnote"><span>${icon('chat-dots')} Anbefalingene er valgfrie. Du velger selv hvor du handler.</span>${btn('Spør legen',"askForRecommendation()",'light small')}</div>`:`<div class="personal-recommendation-empty"><div class="personal-empty-doctor">${portrait(doctor('d2'))}</div><div><h3>Ingen anbefalinger ennå</h3><p>Spør fastlegen om produkter som passer behovet ditt. Beskriv kort hva du ønsker råd om, og hvorfor.</p><strong>Martin Dahl · Fastlegen din</strong></div>${btn('Spør legen '+icon('chat-dots'),"askForRecommendation()")}</div>`}</section>`}
function askForRecommendation(){modal(`<h2>Spør om anbefalte produkter</h2><p>Fortell kort hva du ønsker råd om, og hvorfor.</p><form onsubmit="saveRecommendationRequest(event)"><label>Hva ønsker du hjelp med?<input name="topic" placeholder="For eksempel produkter til tørr hud" required maxlength="120"></label><label>Hvorfor spør du?<textarea name="reason" placeholder="Beskriv behovet ditt kort" required maxlength="500"></textarea></label><small>Forespørselen lagres i denne forhåndsvisningen. Den sendes ikke til legekontoret.</small><div class="actions"><button class="btn" type="submit">Lagre forespørsel</button></div></form>`)}
function saveRecommendationRequest(e){e.preventDefault();let f=new FormData(e.target);db.recommendationRequests=db.recommendationRequests||[];db.recommendationRequests.push({topic:f.get('topic'),reason:f.get('reason'),at:new Date().toISOString()});save();closeModal();toast('Forespørselen er lagret lokalt')}

