function selectAllRx(){for(const r of rxAvailable()){if(!rxInCart(r)&&product(r.product).stock>0)rxSelected.add(r.product)}renderRxList()}

function personalRecommendationCard(r){const p=product(r.product),d=doctor(r.doctor)||doctor('d2'),inCart=db.cart.some(x=>x.id===p.id);return `<article class="personal-recommendation-card"><div class="personal-rec-product-image">${art(p)}</div><div class="personal-rec-main"><span class="product-brand">${esc(p.brand||p.category)}</span><h3>${esc(p.name)}</h3><small>${esc(p.size)}</small><div class="personal-rec-doctor"><div>${portrait(d)}</div><span><strong>${esc(d.name)}</strong><small>Fastlegen din · Spesialist i allmennmedisin</small></span></div><div class="personal-rec-reason"><strong>Derfor har legen valgt dette til deg</strong><p>${esc(r.reason)}</p></div></div><div class="personal-rec-buy"><strong>${money(p.price)}</strong><span>${icon('check-circle')} ${p.stock?'På lager':'Utsolgt'}</span>${btn(inCart?'Legg til én til':icon('bag')+' Legg i kurv',`add('${p.id}')`)}${link('product:'+p.id,'Se produktinformasjon','text-link')}${inCart?'<small class="rec-added">✓ I handlekurven</small>':''}</div></article>`}
function expertProduct(d,p){const matches=db.recommendations.find(r=>!r.personal&&r.product===p.id&&doctor(r.doctor)?.name===d.name),reason=matches?.reason||(p.category==='Solpleie'?'Et produkt i '+d.name.split(' ')[0]+' sitt utvalg for daglig solbeskyttelse.':p.category==='Sår og førstehjelp'?'Et praktisk produkt i '+d.name.split(' ')[0]+' sitt utvalg til førstehjelpsskuffen.':'Et pleieprodukt i '+d.name.split(' ')[0]+' sitt utvalg til den daglige hudrutinen.');return `<div class="expert-product-row"><a href="#product:${p.id}" data-page="product:${p.id}" class="expert-product-image">${art(p)}</a><div><span class="product-brand">${esc(p.brand||p.category)}</span><h3>${link('product:'+p.id,esc(p.name))}</h3><small>${esc(p.size)}</small><p><strong>Hvorfor i utvalget?</strong> ${esc(reason)}</p></div><div class="expert-product-buy"><strong>${money(p.price)}</strong>${btn(icon('bag')+' Legg i kurv',`add('${p.id}')`,'small')}${link('product:'+p.id,'Les mer','text-link')}</div></div>`}

